import{_ as t,o as r,c as a,a6 as s}from"./chunks/framework.CCKCzdWs.js";const p=JSON.parse('{"title":"Bun","description":"Run a Playwright suite under Bun with bunx --bun playwright test: what the Piwi reporter and capture fixtures record there, and the limits that come with Bun.","frontmatter":{"title":"Bun","description":"Run a Playwright suite under Bun with bunx --bun playwright test: what the Piwi reporter and capture fixtures record there, and the limits that come with Bun.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/guide/bun.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/guide/bun.html"}],["meta",{"property":"og:title","content":"Bun | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Run a Playwright suite under Bun with bunx --bun playwright test: what the Piwi reporter and capture fixtures record there, and the limits that come with Bun."}]]},"headers":[],"relativePath":"guide/bun.md","filePath":"guide/bun.md","lastUpdated":1795869546000}'),n={name:"guide/bun.md"};function i(o,e,h,l,d,u){return r(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="bun" tabindex="-1">Bun <a class="header-anchor" href="#bun" aria-label="Permalink to &quot;Bun&quot;">​</a></h1><p>Playwright 1.65 and later run under <a href="https://bun.sh" target="_blank" rel="noreferrer">Bun</a> with <code>bunx --bun playwright test</code>, and so do the Piwi reporter and the <a href="./capture-fixtures.html">capture fixtures</a>: set up as under Node, they send the same results and attachments, with the limits below.</p><h2 id="run-the-suite-under-bun" tabindex="-1">Run the suite under Bun <a class="header-anchor" href="#run-the-suite-under-bun" aria-label="Permalink to &quot;Run the suite under Bun&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bunx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p><code>--bun</code> runs Playwright&#39;s command line on Bun, and the workers it starts run on the same Bun. Without it, <code>bunx</code> follows the script&#39;s <code>node</code> line and the suite runs on Node. Any <code>playwright test</code> option goes after it, as with <code>npx</code>.</p><p>The setup is the <a href="./reporter.html">reporter</a>&#39;s: <code>wrapConfig</code> in <code>playwright.config.ts</code> and the fixtures in your tests. In a project Bun installs (a <code>bun.lock</code>), <code>npx @piwitests/reporter init</code> adds the reporter with <code>bun add -d</code>. The Piwi server is not part of this: it runs on Node, wherever you <a href="/operate/deployment.html">deploy</a> it.</p><h2 id="what-piwi-records" tabindex="-1">What Piwi records <a class="header-anchor" href="#what-piwi-records" aria-label="Permalink to &quot;What Piwi records&quot;">​</a></h2><p>The reporter sends the run as it does under Node: each test&#39;s results, retries, errors and attachments, the traces and screenshots Playwright records, and the capture fixtures&#39; evidence, streamed as the tests finish.</p><p>The <a href="/features/cpu-memory-disk.html#the-panel">machine panel</a> measures the runner, its workers and their browsers by role, as under Node: Piwi tells a worker by the script Playwright runs in it, whichever runtime runs that script.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>The trace has no console.</strong> The trace Playwright records under Bun holds no console messages. The capture fixtures still record them; in a project without the fixtures, the console card cannot be recovered from the trace.</li><li><strong>Call stacks lose their async frames.</strong> Bun&#39;s stacks leave out most of the <code>async</code> frames Node keeps. Where Piwi places something by its stack, such as an error Playwright gives no location or the line that opened a page left open, a call made after an <code>await</code> in a helper or a package can name no line of your tests.</li><li><strong>A test&#39;s column can be off by one.</strong> Under Bun 1.4.4 and later, Playwright can report a test&#39;s column one off (<a href="https://github.com/microsoft/playwright/issues/43934" target="_blank" rel="noreferrer">microsoft/playwright#43934</a>), and Piwi keeps the location it reports. The file and the line are right, and a test&#39;s history does not depend on the column.</li><li><strong>The worker&#39;s event loop busy time is not measured.</strong> Bun&#39;s <code>performance.eventLoopUtilization()</code> reads no idle and no active time, so the panel&#39;s <strong>Workers</strong> line leaves it out and its <strong>Not measured</strong> line names it, and each execution&#39;s Performance tab shows no busy share. The loop&#39;s delay and the context switches are measured.</li><li><strong>No heap after garbage collection.</strong> Bun reports no garbage collections to the performance observer Piwi reads, so a worker&#39;s heap is never judged <a href="/features/resource-leaks.html#what-it-reports">piling up</a>, and the panel&#39;s <strong>Not measured</strong> line names it. Its open file descriptors are still judged.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./reporter.html">Reporter</a>: the setup, the same under Bun</li><li><a href="./capture-fixtures.html">Capture fixtures</a>: what they record</li><li><a href="/features/cpu-memory-disk.html">CPU, memory &amp; disk</a>: the machine panel</li></ul>',13)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
